"""Статья «Из чего состоит цена строительных работ» для раздела «Справочники».

Исходный образец подготовлен ООО «Тэга плюс» (восемь экранов-картинок), здесь он проверен, переработан в текст и дополнен. Рекламный блок убран.
Подтверждено по открытым источникам: постановление Минстройархитектуры от 17.12.2025 № 146 «О применении норм общехозяйственных и общепроизводственных расходов, плановой прибыли»
существует, вступило в силу 13.02.2026, нормы зависят от вида работ и места (город, село); к нормам ОХР и ОПР при реконструкции и модернизации (кроме жилищного фонда) применяется коэффициент 1,1,
к норме плановой прибыли при текущем ремонте 1,115; Инструкция № 116 от 13.10.2025 нормирует ОХР, ОПР и плановую прибыль в процентах от статей, принятых за базу.
Не удалось подтвердить по доступным текстам: значения норм 67,30 % и 61,18 % для городских строительных работ, нижнюю границу k = 0,9 и номера пункта Положения № 1553 (редакция постановления Совмина № 266 от 15.05.2025),
таблицу долей статей. Они даны «по образцу», с оговоркой, что их нужно сверить с текстом актов.
Что убрано: пример расчёта «191 141 руб., 270 комплектов СИЗ, 24,3 человеко-месяца» (набор допущений без основания), ссылка на «практику МАРТ с коэффициентом 0,57 и 0,43» (не подтверждена),
доли статей цены «50–60 %, 10–16 %» (оставлены как ориентиры практики), громкие слова «вне правового поля» заменены нейтральной формулировкой.
Исправлена опечатка в таблице: в группе Б «дополнительная зарплата» 10,08 %, а не 10,68 % (иначе сумма группы не 24,81).
"""
from art_heat import _sec, _ul, _tbl, _note, _box, _p, _kpis
from art_price_figs import f_groups, f_k
from art_vent_figs import ru

PRAVO = "https://pravo.by/document/?guid=12551&p0=W22644580"


def article():
    s = ""
    s += _kpis([("67,30 %", "норма ОХР и ОПР для городских строительных работ, по образцу, к зарплате рабочих и машинистов"), ("61,18 %", "норма плановой прибыли, та же база, по образцу"),
                ("k ≥ 0,9", "граница конкурсного коэффициента по образцу: не больше 10 % снижения"), ("13.02.2026", "дата вступления в силу постановления № 146 с новыми нормами")])
    s += _box("Главное",
              "Смета это не придуманная цифра, а сумма нормативных слагаемых. Основная часть цены это материалы, зарплата и машины. Накладные расходы (ОХР и ОПР) и плановая прибыль считаются от зарплаты рабочих и машинистов по нормам. "
              "На торгах подрядчик может снизить цену, но не ниже границы по конкурсному коэффициенту. Значения норм и границы ниже даны по образцу ООО «Тэга плюс», перед договором сверяйте их с текстом актов.")

    s += _sec("1", "Как цена собирается слой за слоем",
              _tbl(["Слой", "Что это", "Как считается", "Типичная доля, ориентир практики"], [
                  ["Материалы, изделия, конструкции", "Всё, что остаётся в здании", "расход по нормам × текущие цены республиканской базы", "около 50–60 %"],
                  ["Зарплата рабочих и машинистов", "Труд на площадке", "человеко-часы 4-го разряда × затраты труда по нормам", "около 10–16 %"],
                  ["Эксплуатация машин и механизмов", "Техника и вспомогательное", "машино-часы × цена машино-часа", "около 8–12 %"],
                  ["ОХР и ОПР", "Организация, управление и обслуживание строительства", "норма % от базы (зарплата рабочих и машинистов)", "норма, по образцу 67,30 % от базы"],
                  ["Плановая прибыль", "Оборотные средства, потребление, налог на прибыль", "норма % от той же базы", "норма, по образцу 61,18 % от базы"],
                  ["Временные здания, зимнее удорожание, прочее", "Титульные временные здания, зимние, расходы заказчика", "по нормам и смете", "около 3–8 %"],
                  ["НДС, налоги из выручки, взносы в ФРСО", "По законодательству", "ставка налога, НДС по действующей ставке", "по закону"],
                  ["Цена заказчика, цена предложения подрядчика", "Итог", "цена предложения = цена заказчика × k", "k по образцу от 0,9 до 1,0"],
              ])
              + _note("Доли по слоям это ориентиры из практики, они сильно зависят от вида работ. Нормы ОХР, ОПР и плановой прибыли зависят от вида работ (строительные, монтажные, специальные, ремонтные и т. д.) и места (город, село), "
                      "для реконструкции и модернизации (кроме жилищного фонда) к ОХР и ОПР применяется коэффициент 1,1, для текущего ремонта к плановой прибыли 1,115."))

    s += _sec("2", "ОХР и ОПР: куда уходит каждый рубль нормы",
              _p("По образцу, норма ОХР и ОПР для городских строительных работ составляет 67,30 % к зарплате рабочих и машинистов. Внутри неё затраты распределены по четырём группам. "
                 "Постановлением № 146 нормы утверждены с 13.02.2026: по комментариям к нему, в норму для городских работ добавили налог на недвижимость, поэтому она выше прежней. Точные значения для вашего вида работ ищите в приложении 1 к постановлению.")
              + f_groups()
              + _tbl(["Статья нормы", "Доля в норме, %"], [
                  ["Заработная плата аппарата управления, прорабов, охраны, геодезистов, лаборантов, ППР", "48,68"],
                  ["Взносы в ФСЗН и страхование от несчастных случаев", "17,04"],
                  ["Прочие расходы: связь, аудит, налоги, аттестация, страхование, платные дороги", "19,24"],
                  ["Материалы: ГСМ, спецодежда и СИЗ, канцелярия, моющие средства", "5,52"],
                  ["Содержание зданий: коммуналка и ремонт помещений", "3,85"],
                  ["Амортизация основных средств аппарата управления, нематериальных активов, инвентаря, приборов", "3,27"],
                  ["Тепловая энергия", "1,44"],
                  ["Транспортные затраты", "0,54"],
                  ["Электроэнергия", "0,42"],
                  ["Итого", "100,00"],
              ], True)
              + _note("Сумма долей 100,00 проверена, структура взята из образца и таблицы Минстройархитектуры в справочной публикации. Сверьте её с первоисточником."))

    s += _sec("3", "Постатейная структура: четыре группы",
              _tbl(["Группа", "Что в ней", "Статьи (доля внутри нормы, %)"], [
                  ["А. Административно-хозяйственные, 56,37", "Содержание аппарата управления: зарплаты дирекции, прорабов и мастеров с отчислениями, офис, связь, служебные авто и техника",
                   "Зарплата аппарата управления и линейного персонала 35,40; отчисления на соцстрахование АХП 12,39; содержание и эксплуатация зданий 3,13; почта, телеграф, телефон 1,26; вычислительная техника 1,02; служебные разъезды и командировки 0,98; ремонтный фонд ОС аппарата управления 0,95; служебный автотранспорт 0,55; амортизация ОС, износ и ремонт МБП 0,45; канцелярия, типография 0,24"],
                  ["Б. Обслуживание работников, 24,81", "Выплаты людям сверх расценки: допотпуска и доплаты, санбыт, спецодежда и охрана труда, обучение кадров",
                   "Дополнительная зарплата рабочих основного производства 10,08; охрана труда и техника безопасности 6,63; соцстрахование с дополнительной зарплаты 3,74; санитарно-гигиенические и бытовые условия 2,91; подготовка и переподготовка кадров 1,45"],
                  ["В. Организация работ на площадках, 15,13", "Сама площадка: нетитульные времянки, инструмент, охрана, геодезия, ППР, лаборатории, благоустройство и сдача",
                   "Малоценные и быстроизнашивающиеся предметы 4,17; амортизация, ремонт, перемещение приспособлений 2,91; ведомственная, пожарная и сторожевая охрана 2,44; временные (нетитульные) сооружения 1,78; подготовка объектов к сдаче 1,17; благоустройство стройплощадок 0,92; производственные лаборатории 0,49; проектирование производства работ (ППР) 0,48; геодезические работы 0,35; рационализация производства 0,31; перебазирование в пределах стройки 0,11"],
                  ["Г. Прочие накладные, 3,69", "Внешние услуги и платежи: страхование имущества, банки, реклама, аудит, лицензии и торги",
                   "Услуги банков 2,11; реклама, аудит, консультации, информация 0,68; обязательное страхование имущества 0,61; лицензирование, торги и другие расходы 0,29"],
              ])
              + _note("Группа Б в образце содержала опечатку (10,68 вместо 10,08 по первой строке), исправлено так, чтобы сумма группы составляла 24,81."))

    s += _sec("4", "Конкурсный коэффициент: 0,9 это пол, а не потолок торга",
              _p("Конкурсный коэффициент это рассчитываемый подрядчиком коэффициент, учитывающий компенсацию рисков от непредвиденных обстоятельств и его внутренние конкурентные преимущества. "
                 "По образцу, на бюджетных объектах цена предложения подрядчика не может быть ниже цены заказчика более чем на 10 %, то есть k находится в пределах от 0,9 до 1,0 (Положение № 1553, часть 2 пункта 8, в редакции постановления Совмина от 15.05.2025 № 266). "
                 "Действует ли граница для вашей закупки, зависит от вида закупки, источника финансирования и условий конкурса: проверьте по тексту Положения и по конкурсной документации.")
              + f_k()
              + _tbl(["k", "Снижение цены", "Что происходит в смете (ориентир практики, не норма)"], [
                  ["0,90", "−10 %", "Срезается плановая прибыль и часть оборотных средств. Площадка работает штатно, запаса на риски нет."],
                  ["0,85", "−15 %", "Под давлением охрана труда: СИЗ, обучение, аттестация рабочих мест. Менее строгий контроль на объекте."],
                  ["0,75", "−25 %", "Экономят на охране площадки, лаборатории, геодезии, разработке ППР. Работы ведутся «на глаз»."],
                  ["0,57", "−43 %", "Цена ниже возможной себестоимости: признак демпинга или доработок заказчиком."],
              ])
              + _ul(["<b>Это требование закона, а не позиция подрядчика</b>: граница введена против срывов сроков и некачественных работ.",
                     "<b>Снижать физически нечего</b>: по структуре выше 65,72 % массы накладных расходов это зарплата и взносы (48,68 + 17,04), ещё около 19 % налоги, аудит, страхование, аттестация.",
                     "<b>Первыми «экономят» на безопасности</b>: из ОХР и ОПР платят за СИЗ, обучение, аттестацию рабочих мест, охрану площадки, ППР и лабораторию."]))

    s += _sec("5", "Что делать заказчику и подрядчику",
              _ul(["Просите расшифровку цены по слоям: материалы, зарплата, машины, ОХР и ОПР, плановая прибыль, налоги. Если накладные расходы и прибыль в предложении не видны, спросите, как они учтены.",
                   "Сравнивайте предложения по составу работ, а не по итоговой цифре: низкая цена при равном объёме должна объясняться, а не скрываться.",
                   "Для бюджетных закупок проверьте, применим ли к вам нижний предел конкурсного коэффициента и как он указан в документации.",
                   "Для частных договоров сверяйте с условиями договора, какие нормы применяются: ОХР, ОПР и плановая прибыль в любом случае дают понятную точку отсчёта при разговоре о цене.",
                   "Проверяйте актуальность норм: вид работ, город или село, коэффициенты 1,1 и 1,115 для реконструкции и текущего ремонта. Калькулятор сметы на этом сайте считает стоимость ремонта по расценкам, а не по этим нормам."])
              + _note(f'Источники: <a href="{PRAVO}" target="_blank" rel="noopener">постановление Министерства архитектуры и строительства от 17.12.2025 № 146 «О применении норм общехозяйственных и общепроизводственных расходов, плановой прибыли»</a> (действует с 13.02.2026); '
                      "Инструкция № 116 от 13.10.2025; РСН 8.01.105-2007 (по образцу); Положение № 1553 в редакции постановления Совета Министров от 15.05.2025 № 266 (по образцу). "
                      "Значения норм и границы коэффициента даны по образцу ООО «Тэга плюс» и перед применением в договоре сверяются с текстом актов специалистом. Справка не является расчётом сметы."))
    return s
